import{_ as o,J as r,b as t,e as n,a8 as i,f as a,L as l}from"./chunks/framework.CumEd6mW.js";const m=JSON.parse('{"title":"GR32_Brushes","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32_Brushes","entity":"GR32_Brushes","kind":"Unit","summary":"Provides vector polygon brush effects including solid filling, stroking, growing, dashing, and nested brush pipelines.","title":"GR32_Brushes","date":1788949297000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32_Brushes/index.md","filePath":"api/GR32_Brushes/index.md","lastUpdated":1788949297000,"timestamp":1788949297000,"datetime":"2026-09-09T10:21:37.000Z"}'),d={name:"api/GR32_Brushes/index.md"};function h(u,e,c,p,g,B){const s=r("ApiMembers");return t(),n("div",null,[e[0]||(e[0]=i('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p>The <code>GR32_Brushes</code> unit provides a modular vector brush architecture for rendering vector paths and polygons in Graphics32.</p><p>Brushes encapsulate polygon drawing behaviors (such as outline stroking, polygon expansion/shrinking, dashed pattern generation, and solid color/filler assignment) and can be chained together in brush collections or composite nested brushes.</p><p>Key classes and types in <code>GR32_Brushes</code> include:</p><ul><li><strong>Brush Collection</strong>: <a href="/api/GR32_Brushes/TBrushCollection/">TBrushCollection</a> manages an ordered list of brush instances assigned to an owner object.</li><li><strong>Base Class</strong>: <a href="/api/GR32_Brushes/TCustomBrush/">TCustomBrush</a> defines the fundamental interface and pipeline methods for vector path processing and rendering (<code>PolygonFS</code>, <code>PolyPolygonFS</code>, <code>PolyPolygonMixedFS</code>).</li><li><strong>Solid Brush</strong>: <a href="/api/GR32_Brushes/TSolidBrush/">TSolidBrush</a> applies fill color, fill mode, or custom polygon fillers (<a href="/api/GR32_Polygons/TCustomPolygonFiller/">TCustomPolygonFiller</a>) to vector shapes.</li><li><strong>Nested Brush</strong>: <a href="/api/GR32_Brushes/TNestedBrush/">TNestedBrush</a> contains its own child <a href="/api/GR32_Brushes/TBrushCollection/">TBrushCollection</a>, executing multiple brush effects sequentially on the same geometry.</li><li><strong>Stroke Brush</strong>: <a href="/api/GR32_Brushes/TStrokeBrush/">TStrokeBrush</a> converts closed or open vector paths into stroked outlines using specified line widths, join styles, end styles, and miter limits.</li><li><strong>Grow Brush</strong>: <a href="/api/GR32_Brushes/TGrowBrush/">TGrowBrush</a> inflates or deflates polygon boundaries by a floating-point grow amount.</li><li><strong>Dashed Brush</strong>: <a href="/api/GR32_Brushes/TDashedBrush/">TDashedBrush</a> splits vector outlines into dashed line segments using custom dash pattern arrays and offsets before stroking.</li></ul>',5)),a("p",null,[l(s,{type:"members"})])])}const _=o(d,[["render",h]]);export{m as __pageData,_ as default};
